-- stochastic-processes implementation for HiddenMarkovModel
-- Assumptions: stochastic increments use the specified time step; physical SDE parameters use SI units and random draws are supplied or generated by the documented stream.
local ReplicatedStorage = game:GetService("ReplicatedStorage")
local Shared = ReplicatedStorage:WaitForChild("VectorForgeShared")
local Num = require(Shared:WaitForChild("NumericalKernels"))

local Module = {}
function Module.Forward(observations,transition,emission,initial)
    local states=#initial; assert(#transition==states and #emission==states,"HMM state dimensions mismatch")
    local alpha=table.clone(initial); local scaleFactors={}
    for t=1,#observations do
        local nextAlpha=table.create(states,0); local normalizer=0
        for j=1,states do
            local predicted=0; for i=1,states do predicted+=alpha[i]*transition[i][j] end
            nextAlpha[j]=predicted*emission[j][observations[t]]; normalizer+=nextAlpha[j]
        end
        Num.Positive(normalizer,"HMM observation likelihood")
        for j=1,states do nextAlpha[j]/=normalizer end
        alpha=nextAlpha; scaleFactors[t]=normalizer
    end
    local logLikelihood=0; for _,factor in ipairs(scaleFactors) do logLikelihood+=math.log(factor) end
    return alpha,logLikelihood
end

return Module
